package com.pradarshana.core.model

data class BabaAnswer(
    val number: Int,
    val english: String,
    val telugu: String,
)

/**
 * Original guidance for personal prayer, one message for each number from 1 to 720.
 * These words are not taken from a published question book.
 */
object AskBaba {
    const val MIN = 1
    const val MAX = 720

    fun answer(number: Int): BabaAnswer? {
        if (number !in MIN..MAX) return null
        return answers[number - 1]
    }

    private val answers: List<BabaAnswer> = listOf(
        BabaAnswer(1, "Keep faith in Baba, even when the path is not clear. Remember Baba and take the next step without fear.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(2, "Patience will open the door that hurry keeps shut. Remember Baba and take the next step without fear.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(3, "Speak the truth gently, and your mind will grow quiet. Remember Baba and take the next step without fear.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(4, "Give a little today, without waiting to be asked. Remember Baba and take the next step without fear.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(5, "What you are waiting for is already on its way. Remember Baba and take the next step without fear.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(6, "Do the work in front of you, and leave the result to Baba. Remember Baba and take the next step without fear.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(7, "A calm mind will see the answer you are searching for. Remember Baba and take the next step without fear.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(8, "Forgive the hurt, and you will sleep in peace. Remember Baba and take the next step without fear.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(9, "This delay is protection, not a refusal. Remember Baba and take the next step without fear.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(10, "Begin the good work you have been postponing. Remember Baba and take the next step without fear.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(11, "Your family will find peace if you speak with kindness. Remember Baba and take the next step without fear.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(12, "Health returns when rest and prayer walk together. Remember Baba and take the next step without fear.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(13, "Do not compare your life with another person's path. Remember Baba and take the next step without fear.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(14, "The worry you carry is heavier than the work itself. Remember Baba and take the next step without fear.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(15, "Offer your fear at Baba's feet and take the next honest step. Remember Baba and take the next step without fear.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(16, "A small act of service will lighten this problem. Remember Baba and take the next step without fear.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(17, "Wait with a steady heart. The right time is near. Remember Baba and take the next step without fear.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(18, "What looks like a loss will teach you something precious. Remember Baba and take the next step without fear.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(19, "Keep your word, even in a small matter. Remember Baba and take the next step without fear.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(20, "Prayer in the morning will steady the whole day. Remember Baba and take the next step without fear.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(21, "Share what you can, and Baba will fill what you lack. Remember Baba and take the next step without fear.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(22, "Do not force a yes or a no. Let the truth ripen. Remember Baba and take the next step without fear.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(23, "The person you are thinking of needs your patience. Remember Baba and take the next step without fear.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(24, "Go to the temple, sit quietly, and listen. Remember Baba and take the next step without fear.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(25, "Your effort is seen. Do not abandon it halfway. Remember Baba and take the next step without fear.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(26, "Anger will spoil a good result. Speak tomorrow instead. Remember Baba and take the next step without fear.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(27, "Money spent for a good cause will return as peace. Remember Baba and take the next step without fear.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(28, "Trust the slow progress. It is still progress. Remember Baba and take the next step without fear.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(29, "Baba asks you to be kind to yourself today. Remember Baba and take the next step without fear.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(30, "Hold one question, not ten. Clarity comes to a quiet mind. Remember Baba and take the next step without fear.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. బాబాను స్మరించి, భయం లేకుండా తర్వాతి అడుగు వేయండి."),
        BabaAnswer(31, "Keep faith in Baba, even when the path is not clear. Faith and perseverance will carry you through this.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(32, "Patience will open the door that hurry keeps shut. Faith and perseverance will carry you through this.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(33, "Speak the truth gently, and your mind will grow quiet. Faith and perseverance will carry you through this.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(34, "Give a little today, without waiting to be asked. Faith and perseverance will carry you through this.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(35, "What you are waiting for is already on its way. Faith and perseverance will carry you through this.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(36, "Do the work in front of you, and leave the result to Baba. Faith and perseverance will carry you through this.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(37, "A calm mind will see the answer you are searching for. Faith and perseverance will carry you through this.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(38, "Forgive the hurt, and you will sleep in peace. Faith and perseverance will carry you through this.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(39, "This delay is protection, not a refusal. Faith and perseverance will carry you through this.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(40, "Begin the good work you have been postponing. Faith and perseverance will carry you through this.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(41, "Your family will find peace if you speak with kindness. Faith and perseverance will carry you through this.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(42, "Health returns when rest and prayer walk together. Faith and perseverance will carry you through this.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(43, "Do not compare your life with another person's path. Faith and perseverance will carry you through this.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(44, "The worry you carry is heavier than the work itself. Faith and perseverance will carry you through this.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(45, "Offer your fear at Baba's feet and take the next honest step. Faith and perseverance will carry you through this.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(46, "A small act of service will lighten this problem. Faith and perseverance will carry you through this.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(47, "Wait with a steady heart. The right time is near. Faith and perseverance will carry you through this.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(48, "What looks like a loss will teach you something precious. Faith and perseverance will carry you through this.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(49, "Keep your word, even in a small matter. Faith and perseverance will carry you through this.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(50, "Prayer in the morning will steady the whole day. Faith and perseverance will carry you through this.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(51, "Share what you can, and Baba will fill what you lack. Faith and perseverance will carry you through this.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(52, "Do not force a yes or a no. Let the truth ripen. Faith and perseverance will carry you through this.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(53, "The person you are thinking of needs your patience. Faith and perseverance will carry you through this.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(54, "Go to the temple, sit quietly, and listen. Faith and perseverance will carry you through this.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(55, "Your effort is seen. Do not abandon it halfway. Faith and perseverance will carry you through this.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(56, "Anger will spoil a good result. Speak tomorrow instead. Faith and perseverance will carry you through this.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(57, "Money spent for a good cause will return as peace. Faith and perseverance will carry you through this.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(58, "Trust the slow progress. It is still progress. Faith and perseverance will carry you through this.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(59, "Baba asks you to be kind to yourself today. Faith and perseverance will carry you through this.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(60, "Hold one question, not ten. Clarity comes to a quiet mind. Faith and perseverance will carry you through this.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. విశ్వాసం మరియు పట్టుదల ఈ పరిస్థితిని దాటిస్తాయి."),
        BabaAnswer(61, "Keep faith in Baba, even when the path is not clear. Do not ask again out of doubt. One sincere prayer is enough.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(62, "Patience will open the door that hurry keeps shut. Do not ask again out of doubt. One sincere prayer is enough.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(63, "Speak the truth gently, and your mind will grow quiet. Do not ask again out of doubt. One sincere prayer is enough.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(64, "Give a little today, without waiting to be asked. Do not ask again out of doubt. One sincere prayer is enough.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(65, "What you are waiting for is already on its way. Do not ask again out of doubt. One sincere prayer is enough.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(66, "Do the work in front of you, and leave the result to Baba. Do not ask again out of doubt. One sincere prayer is enough.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(67, "A calm mind will see the answer you are searching for. Do not ask again out of doubt. One sincere prayer is enough.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(68, "Forgive the hurt, and you will sleep in peace. Do not ask again out of doubt. One sincere prayer is enough.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(69, "This delay is protection, not a refusal. Do not ask again out of doubt. One sincere prayer is enough.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(70, "Begin the good work you have been postponing. Do not ask again out of doubt. One sincere prayer is enough.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(71, "Your family will find peace if you speak with kindness. Do not ask again out of doubt. One sincere prayer is enough.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(72, "Health returns when rest and prayer walk together. Do not ask again out of doubt. One sincere prayer is enough.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(73, "Do not compare your life with another person's path. Do not ask again out of doubt. One sincere prayer is enough.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(74, "The worry you carry is heavier than the work itself. Do not ask again out of doubt. One sincere prayer is enough.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(75, "Offer your fear at Baba's feet and take the next honest step. Do not ask again out of doubt. One sincere prayer is enough.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(76, "A small act of service will lighten this problem. Do not ask again out of doubt. One sincere prayer is enough.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(77, "Wait with a steady heart. The right time is near. Do not ask again out of doubt. One sincere prayer is enough.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(78, "What looks like a loss will teach you something precious. Do not ask again out of doubt. One sincere prayer is enough.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(79, "Keep your word, even in a small matter. Do not ask again out of doubt. One sincere prayer is enough.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(80, "Prayer in the morning will steady the whole day. Do not ask again out of doubt. One sincere prayer is enough.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(81, "Share what you can, and Baba will fill what you lack. Do not ask again out of doubt. One sincere prayer is enough.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(82, "Do not force a yes or a no. Let the truth ripen. Do not ask again out of doubt. One sincere prayer is enough.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(83, "The person you are thinking of needs your patience. Do not ask again out of doubt. One sincere prayer is enough.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(84, "Go to the temple, sit quietly, and listen. Do not ask again out of doubt. One sincere prayer is enough.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(85, "Your effort is seen. Do not abandon it halfway. Do not ask again out of doubt. One sincere prayer is enough.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(86, "Anger will spoil a good result. Speak tomorrow instead. Do not ask again out of doubt. One sincere prayer is enough.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(87, "Money spent for a good cause will return as peace. Do not ask again out of doubt. One sincere prayer is enough.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(88, "Trust the slow progress. It is still progress. Do not ask again out of doubt. One sincere prayer is enough.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(89, "Baba asks you to be kind to yourself today. Do not ask again out of doubt. One sincere prayer is enough.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(90, "Hold one question, not ten. Clarity comes to a quiet mind. Do not ask again out of doubt. One sincere prayer is enough.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. సందేహంతో మళ్లీ అడగకండి. ఒక్క నిజాయితీ ప్రార్థన చాలు."),
        BabaAnswer(91, "Keep faith in Baba, even when the path is not clear. Help someone poorer than you before the day ends.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(92, "Patience will open the door that hurry keeps shut. Help someone poorer than you before the day ends.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(93, "Speak the truth gently, and your mind will grow quiet. Help someone poorer than you before the day ends.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(94, "Give a little today, without waiting to be asked. Help someone poorer than you before the day ends.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(95, "What you are waiting for is already on its way. Help someone poorer than you before the day ends.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(96, "Do the work in front of you, and leave the result to Baba. Help someone poorer than you before the day ends.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(97, "A calm mind will see the answer you are searching for. Help someone poorer than you before the day ends.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(98, "Forgive the hurt, and you will sleep in peace. Help someone poorer than you before the day ends.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(99, "This delay is protection, not a refusal. Help someone poorer than you before the day ends.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(100, "Begin the good work you have been postponing. Help someone poorer than you before the day ends.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(101, "Your family will find peace if you speak with kindness. Help someone poorer than you before the day ends.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(102, "Health returns when rest and prayer walk together. Help someone poorer than you before the day ends.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(103, "Do not compare your life with another person's path. Help someone poorer than you before the day ends.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(104, "The worry you carry is heavier than the work itself. Help someone poorer than you before the day ends.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(105, "Offer your fear at Baba's feet and take the next honest step. Help someone poorer than you before the day ends.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(106, "A small act of service will lighten this problem. Help someone poorer than you before the day ends.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(107, "Wait with a steady heart. The right time is near. Help someone poorer than you before the day ends.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(108, "What looks like a loss will teach you something precious. Help someone poorer than you before the day ends.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(109, "Keep your word, even in a small matter. Help someone poorer than you before the day ends.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(110, "Prayer in the morning will steady the whole day. Help someone poorer than you before the day ends.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(111, "Share what you can, and Baba will fill what you lack. Help someone poorer than you before the day ends.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(112, "Do not force a yes or a no. Let the truth ripen. Help someone poorer than you before the day ends.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(113, "The person you are thinking of needs your patience. Help someone poorer than you before the day ends.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(114, "Go to the temple, sit quietly, and listen. Help someone poorer than you before the day ends.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(115, "Your effort is seen. Do not abandon it halfway. Help someone poorer than you before the day ends.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(116, "Anger will spoil a good result. Speak tomorrow instead. Help someone poorer than you before the day ends.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(117, "Money spent for a good cause will return as peace. Help someone poorer than you before the day ends.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(118, "Trust the slow progress. It is still progress. Help someone poorer than you before the day ends.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(119, "Baba asks you to be kind to yourself today. Help someone poorer than you before the day ends.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(120, "Hold one question, not ten. Clarity comes to a quiet mind. Help someone poorer than you before the day ends.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. రోజు ముగియకముందు మీకంటే ఇబ్బందిలో ఉన్నవారికి సహాయం చేయండి."),
        BabaAnswer(121, "Keep faith in Baba, even when the path is not clear. The outcome will be good if you stay honest.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(122, "Patience will open the door that hurry keeps shut. The outcome will be good if you stay honest.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(123, "Speak the truth gently, and your mind will grow quiet. The outcome will be good if you stay honest.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(124, "Give a little today, without waiting to be asked. The outcome will be good if you stay honest.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(125, "What you are waiting for is already on its way. The outcome will be good if you stay honest.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(126, "Do the work in front of you, and leave the result to Baba. The outcome will be good if you stay honest.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(127, "A calm mind will see the answer you are searching for. The outcome will be good if you stay honest.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(128, "Forgive the hurt, and you will sleep in peace. The outcome will be good if you stay honest.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(129, "This delay is protection, not a refusal. The outcome will be good if you stay honest.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(130, "Begin the good work you have been postponing. The outcome will be good if you stay honest.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(131, "Your family will find peace if you speak with kindness. The outcome will be good if you stay honest.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(132, "Health returns when rest and prayer walk together. The outcome will be good if you stay honest.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(133, "Do not compare your life with another person's path. The outcome will be good if you stay honest.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(134, "The worry you carry is heavier than the work itself. The outcome will be good if you stay honest.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(135, "Offer your fear at Baba's feet and take the next honest step. The outcome will be good if you stay honest.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(136, "A small act of service will lighten this problem. The outcome will be good if you stay honest.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(137, "Wait with a steady heart. The right time is near. The outcome will be good if you stay honest.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(138, "What looks like a loss will teach you something precious. The outcome will be good if you stay honest.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(139, "Keep your word, even in a small matter. The outcome will be good if you stay honest.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(140, "Prayer in the morning will steady the whole day. The outcome will be good if you stay honest.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(141, "Share what you can, and Baba will fill what you lack. The outcome will be good if you stay honest.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(142, "Do not force a yes or a no. Let the truth ripen. The outcome will be good if you stay honest.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(143, "The person you are thinking of needs your patience. The outcome will be good if you stay honest.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(144, "Go to the temple, sit quietly, and listen. The outcome will be good if you stay honest.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(145, "Your effort is seen. Do not abandon it halfway. The outcome will be good if you stay honest.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(146, "Anger will spoil a good result. Speak tomorrow instead. The outcome will be good if you stay honest.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(147, "Money spent for a good cause will return as peace. The outcome will be good if you stay honest.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(148, "Trust the slow progress. It is still progress. The outcome will be good if you stay honest.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(149, "Baba asks you to be kind to yourself today. The outcome will be good if you stay honest.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(150, "Hold one question, not ten. Clarity comes to a quiet mind. The outcome will be good if you stay honest.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. మీరు నిజాయితీగా ఉంటే ఫలితం మంచిదే అవుతుంది."),
        BabaAnswer(151, "Keep faith in Baba, even when the path is not clear. A difficulty at home will soften if you listen more than you speak.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(152, "Patience will open the door that hurry keeps shut. A difficulty at home will soften if you listen more than you speak.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(153, "Speak the truth gently, and your mind will grow quiet. A difficulty at home will soften if you listen more than you speak.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(154, "Give a little today, without waiting to be asked. A difficulty at home will soften if you listen more than you speak.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(155, "What you are waiting for is already on its way. A difficulty at home will soften if you listen more than you speak.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(156, "Do the work in front of you, and leave the result to Baba. A difficulty at home will soften if you listen more than you speak.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(157, "A calm mind will see the answer you are searching for. A difficulty at home will soften if you listen more than you speak.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(158, "Forgive the hurt, and you will sleep in peace. A difficulty at home will soften if you listen more than you speak.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(159, "This delay is protection, not a refusal. A difficulty at home will soften if you listen more than you speak.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(160, "Begin the good work you have been postponing. A difficulty at home will soften if you listen more than you speak.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(161, "Your family will find peace if you speak with kindness. A difficulty at home will soften if you listen more than you speak.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(162, "Health returns when rest and prayer walk together. A difficulty at home will soften if you listen more than you speak.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(163, "Do not compare your life with another person's path. A difficulty at home will soften if you listen more than you speak.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(164, "The worry you carry is heavier than the work itself. A difficulty at home will soften if you listen more than you speak.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(165, "Offer your fear at Baba's feet and take the next honest step. A difficulty at home will soften if you listen more than you speak.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(166, "A small act of service will lighten this problem. A difficulty at home will soften if you listen more than you speak.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(167, "Wait with a steady heart. The right time is near. A difficulty at home will soften if you listen more than you speak.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(168, "What looks like a loss will teach you something precious. A difficulty at home will soften if you listen more than you speak.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(169, "Keep your word, even in a small matter. A difficulty at home will soften if you listen more than you speak.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(170, "Prayer in the morning will steady the whole day. A difficulty at home will soften if you listen more than you speak.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(171, "Share what you can, and Baba will fill what you lack. A difficulty at home will soften if you listen more than you speak.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(172, "Do not force a yes or a no. Let the truth ripen. A difficulty at home will soften if you listen more than you speak.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(173, "The person you are thinking of needs your patience. A difficulty at home will soften if you listen more than you speak.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(174, "Go to the temple, sit quietly, and listen. A difficulty at home will soften if you listen more than you speak.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(175, "Your effort is seen. Do not abandon it halfway. A difficulty at home will soften if you listen more than you speak.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(176, "Anger will spoil a good result. Speak tomorrow instead. A difficulty at home will soften if you listen more than you speak.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(177, "Money spent for a good cause will return as peace. A difficulty at home will soften if you listen more than you speak.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(178, "Trust the slow progress. It is still progress. A difficulty at home will soften if you listen more than you speak.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(179, "Baba asks you to be kind to yourself today. A difficulty at home will soften if you listen more than you speak.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(180, "Hold one question, not ten. Clarity comes to a quiet mind. A difficulty at home will soften if you listen more than you speak.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. మాట్లాడినదానికంటే ఎక్కువగా వింటే ఇంటి కష్టం తగ్గుతుంది."),
        BabaAnswer(181, "Keep faith in Baba, even when the path is not clear. Your work will succeed when you stop rushing the people around you.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(182, "Patience will open the door that hurry keeps shut. Your work will succeed when you stop rushing the people around you.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(183, "Speak the truth gently, and your mind will grow quiet. Your work will succeed when you stop rushing the people around you.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(184, "Give a little today, without waiting to be asked. Your work will succeed when you stop rushing the people around you.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(185, "What you are waiting for is already on its way. Your work will succeed when you stop rushing the people around you.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(186, "Do the work in front of you, and leave the result to Baba. Your work will succeed when you stop rushing the people around you.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(187, "A calm mind will see the answer you are searching for. Your work will succeed when you stop rushing the people around you.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(188, "Forgive the hurt, and you will sleep in peace. Your work will succeed when you stop rushing the people around you.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(189, "This delay is protection, not a refusal. Your work will succeed when you stop rushing the people around you.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(190, "Begin the good work you have been postponing. Your work will succeed when you stop rushing the people around you.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(191, "Your family will find peace if you speak with kindness. Your work will succeed when you stop rushing the people around you.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(192, "Health returns when rest and prayer walk together. Your work will succeed when you stop rushing the people around you.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(193, "Do not compare your life with another person's path. Your work will succeed when you stop rushing the people around you.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(194, "The worry you carry is heavier than the work itself. Your work will succeed when you stop rushing the people around you.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(195, "Offer your fear at Baba's feet and take the next honest step. Your work will succeed when you stop rushing the people around you.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(196, "A small act of service will lighten this problem. Your work will succeed when you stop rushing the people around you.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(197, "Wait with a steady heart. The right time is near. Your work will succeed when you stop rushing the people around you.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(198, "What looks like a loss will teach you something precious. Your work will succeed when you stop rushing the people around you.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(199, "Keep your word, even in a small matter. Your work will succeed when you stop rushing the people around you.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(200, "Prayer in the morning will steady the whole day. Your work will succeed when you stop rushing the people around you.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(201, "Share what you can, and Baba will fill what you lack. Your work will succeed when you stop rushing the people around you.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(202, "Do not force a yes or a no. Let the truth ripen. Your work will succeed when you stop rushing the people around you.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(203, "The person you are thinking of needs your patience. Your work will succeed when you stop rushing the people around you.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(204, "Go to the temple, sit quietly, and listen. Your work will succeed when you stop rushing the people around you.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(205, "Your effort is seen. Do not abandon it halfway. Your work will succeed when you stop rushing the people around you.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(206, "Anger will spoil a good result. Speak tomorrow instead. Your work will succeed when you stop rushing the people around you.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(207, "Money spent for a good cause will return as peace. Your work will succeed when you stop rushing the people around you.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(208, "Trust the slow progress. It is still progress. Your work will succeed when you stop rushing the people around you.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(209, "Baba asks you to be kind to yourself today. Your work will succeed when you stop rushing the people around you.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(210, "Hold one question, not ten. Clarity comes to a quiet mind. Your work will succeed when you stop rushing the people around you.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. చుట్టూ ఉన్నవారిని తొందరపెట్టడం మానితే మీ పని సఫలమవుతుంది."),
        BabaAnswer(211, "Keep faith in Baba, even when the path is not clear. Rest tonight. The body you neglect cannot carry your prayer.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(212, "Patience will open the door that hurry keeps shut. Rest tonight. The body you neglect cannot carry your prayer.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(213, "Speak the truth gently, and your mind will grow quiet. Rest tonight. The body you neglect cannot carry your prayer.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(214, "Give a little today, without waiting to be asked. Rest tonight. The body you neglect cannot carry your prayer.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(215, "What you are waiting for is already on its way. Rest tonight. The body you neglect cannot carry your prayer.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(216, "Do the work in front of you, and leave the result to Baba. Rest tonight. The body you neglect cannot carry your prayer.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(217, "A calm mind will see the answer you are searching for. Rest tonight. The body you neglect cannot carry your prayer.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(218, "Forgive the hurt, and you will sleep in peace. Rest tonight. The body you neglect cannot carry your prayer.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(219, "This delay is protection, not a refusal. Rest tonight. The body you neglect cannot carry your prayer.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(220, "Begin the good work you have been postponing. Rest tonight. The body you neglect cannot carry your prayer.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(221, "Your family will find peace if you speak with kindness. Rest tonight. The body you neglect cannot carry your prayer.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(222, "Health returns when rest and prayer walk together. Rest tonight. The body you neglect cannot carry your prayer.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(223, "Do not compare your life with another person's path. Rest tonight. The body you neglect cannot carry your prayer.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(224, "The worry you carry is heavier than the work itself. Rest tonight. The body you neglect cannot carry your prayer.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(225, "Offer your fear at Baba's feet and take the next honest step. Rest tonight. The body you neglect cannot carry your prayer.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(226, "A small act of service will lighten this problem. Rest tonight. The body you neglect cannot carry your prayer.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(227, "Wait with a steady heart. The right time is near. Rest tonight. The body you neglect cannot carry your prayer.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(228, "What looks like a loss will teach you something precious. Rest tonight. The body you neglect cannot carry your prayer.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(229, "Keep your word, even in a small matter. Rest tonight. The body you neglect cannot carry your prayer.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(230, "Prayer in the morning will steady the whole day. Rest tonight. The body you neglect cannot carry your prayer.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(231, "Share what you can, and Baba will fill what you lack. Rest tonight. The body you neglect cannot carry your prayer.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(232, "Do not force a yes or a no. Let the truth ripen. Rest tonight. The body you neglect cannot carry your prayer.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(233, "The person you are thinking of needs your patience. Rest tonight. The body you neglect cannot carry your prayer.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(234, "Go to the temple, sit quietly, and listen. Rest tonight. The body you neglect cannot carry your prayer.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(235, "Your effort is seen. Do not abandon it halfway. Rest tonight. The body you neglect cannot carry your prayer.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(236, "Anger will spoil a good result. Speak tomorrow instead. Rest tonight. The body you neglect cannot carry your prayer.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(237, "Money spent for a good cause will return as peace. Rest tonight. The body you neglect cannot carry your prayer.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(238, "Trust the slow progress. It is still progress. Rest tonight. The body you neglect cannot carry your prayer.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(239, "Baba asks you to be kind to yourself today. Rest tonight. The body you neglect cannot carry your prayer.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(240, "Hold one question, not ten. Clarity comes to a quiet mind. Rest tonight. The body you neglect cannot carry your prayer.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. ఈ రాత్రి విశ్రాంతి తీసుకోండి. నిర్లక్ష్యం చేసే శరీరం ప్రార్థనను మోయలేదు."),
        BabaAnswer(241, "Keep faith in Baba, even when the path is not clear. Let go of the old quarrel. It has taken enough of your peace.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(242, "Patience will open the door that hurry keeps shut. Let go of the old quarrel. It has taken enough of your peace.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(243, "Speak the truth gently, and your mind will grow quiet. Let go of the old quarrel. It has taken enough of your peace.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(244, "Give a little today, without waiting to be asked. Let go of the old quarrel. It has taken enough of your peace.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(245, "What you are waiting for is already on its way. Let go of the old quarrel. It has taken enough of your peace.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(246, "Do the work in front of you, and leave the result to Baba. Let go of the old quarrel. It has taken enough of your peace.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(247, "A calm mind will see the answer you are searching for. Let go of the old quarrel. It has taken enough of your peace.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(248, "Forgive the hurt, and you will sleep in peace. Let go of the old quarrel. It has taken enough of your peace.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(249, "This delay is protection, not a refusal. Let go of the old quarrel. It has taken enough of your peace.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(250, "Begin the good work you have been postponing. Let go of the old quarrel. It has taken enough of your peace.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(251, "Your family will find peace if you speak with kindness. Let go of the old quarrel. It has taken enough of your peace.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(252, "Health returns when rest and prayer walk together. Let go of the old quarrel. It has taken enough of your peace.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(253, "Do not compare your life with another person's path. Let go of the old quarrel. It has taken enough of your peace.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(254, "The worry you carry is heavier than the work itself. Let go of the old quarrel. It has taken enough of your peace.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(255, "Offer your fear at Baba's feet and take the next honest step. Let go of the old quarrel. It has taken enough of your peace.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(256, "A small act of service will lighten this problem. Let go of the old quarrel. It has taken enough of your peace.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(257, "Wait with a steady heart. The right time is near. Let go of the old quarrel. It has taken enough of your peace.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(258, "What looks like a loss will teach you something precious. Let go of the old quarrel. It has taken enough of your peace.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(259, "Keep your word, even in a small matter. Let go of the old quarrel. It has taken enough of your peace.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(260, "Prayer in the morning will steady the whole day. Let go of the old quarrel. It has taken enough of your peace.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(261, "Share what you can, and Baba will fill what you lack. Let go of the old quarrel. It has taken enough of your peace.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(262, "Do not force a yes or a no. Let the truth ripen. Let go of the old quarrel. It has taken enough of your peace.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(263, "The person you are thinking of needs your patience. Let go of the old quarrel. It has taken enough of your peace.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(264, "Go to the temple, sit quietly, and listen. Let go of the old quarrel. It has taken enough of your peace.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(265, "Your effort is seen. Do not abandon it halfway. Let go of the old quarrel. It has taken enough of your peace.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(266, "Anger will spoil a good result. Speak tomorrow instead. Let go of the old quarrel. It has taken enough of your peace.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(267, "Money spent for a good cause will return as peace. Let go of the old quarrel. It has taken enough of your peace.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(268, "Trust the slow progress. It is still progress. Let go of the old quarrel. It has taken enough of your peace.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(269, "Baba asks you to be kind to yourself today. Let go of the old quarrel. It has taken enough of your peace.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(270, "Hold one question, not ten. Clarity comes to a quiet mind. Let go of the old quarrel. It has taken enough of your peace.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. పాత వాదనను వదిలేయండి. అది మీ శాంతిని చాలా తీసుకుంది."),
        BabaAnswer(271, "Keep faith in Baba, even when the path is not clear. Give thanks for what is already in your hands.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(272, "Patience will open the door that hurry keeps shut. Give thanks for what is already in your hands.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(273, "Speak the truth gently, and your mind will grow quiet. Give thanks for what is already in your hands.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(274, "Give a little today, without waiting to be asked. Give thanks for what is already in your hands.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(275, "What you are waiting for is already on its way. Give thanks for what is already in your hands.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(276, "Do the work in front of you, and leave the result to Baba. Give thanks for what is already in your hands.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(277, "A calm mind will see the answer you are searching for. Give thanks for what is already in your hands.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(278, "Forgive the hurt, and you will sleep in peace. Give thanks for what is already in your hands.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(279, "This delay is protection, not a refusal. Give thanks for what is already in your hands.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(280, "Begin the good work you have been postponing. Give thanks for what is already in your hands.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(281, "Your family will find peace if you speak with kindness. Give thanks for what is already in your hands.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(282, "Health returns when rest and prayer walk together. Give thanks for what is already in your hands.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(283, "Do not compare your life with another person's path. Give thanks for what is already in your hands.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(284, "The worry you carry is heavier than the work itself. Give thanks for what is already in your hands.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(285, "Offer your fear at Baba's feet and take the next honest step. Give thanks for what is already in your hands.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(286, "A small act of service will lighten this problem. Give thanks for what is already in your hands.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(287, "Wait with a steady heart. The right time is near. Give thanks for what is already in your hands.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(288, "What looks like a loss will teach you something precious. Give thanks for what is already in your hands.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(289, "Keep your word, even in a small matter. Give thanks for what is already in your hands.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(290, "Prayer in the morning will steady the whole day. Give thanks for what is already in your hands.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(291, "Share what you can, and Baba will fill what you lack. Give thanks for what is already in your hands.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(292, "Do not force a yes or a no. Let the truth ripen. Give thanks for what is already in your hands.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(293, "The person you are thinking of needs your patience. Give thanks for what is already in your hands.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(294, "Go to the temple, sit quietly, and listen. Give thanks for what is already in your hands.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(295, "Your effort is seen. Do not abandon it halfway. Give thanks for what is already in your hands.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(296, "Anger will spoil a good result. Speak tomorrow instead. Give thanks for what is already in your hands.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(297, "Money spent for a good cause will return as peace. Give thanks for what is already in your hands.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(298, "Trust the slow progress. It is still progress. Give thanks for what is already in your hands.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(299, "Baba asks you to be kind to yourself today. Give thanks for what is already in your hands.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(300, "Hold one question, not ten. Clarity comes to a quiet mind. Give thanks for what is already in your hands.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. ఇప్పటికే మీ చేతిలో ఉన్నదానికి కృతజ్ఞత చెప్పండి."),
        BabaAnswer(301, "Keep faith in Baba, even when the path is not clear. A journey or a visit will bring useful news.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(302, "Patience will open the door that hurry keeps shut. A journey or a visit will bring useful news.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(303, "Speak the truth gently, and your mind will grow quiet. A journey or a visit will bring useful news.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(304, "Give a little today, without waiting to be asked. A journey or a visit will bring useful news.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(305, "What you are waiting for is already on its way. A journey or a visit will bring useful news.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(306, "Do the work in front of you, and leave the result to Baba. A journey or a visit will bring useful news.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(307, "A calm mind will see the answer you are searching for. A journey or a visit will bring useful news.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(308, "Forgive the hurt, and you will sleep in peace. A journey or a visit will bring useful news.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(309, "This delay is protection, not a refusal. A journey or a visit will bring useful news.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(310, "Begin the good work you have been postponing. A journey or a visit will bring useful news.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(311, "Your family will find peace if you speak with kindness. A journey or a visit will bring useful news.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(312, "Health returns when rest and prayer walk together. A journey or a visit will bring useful news.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(313, "Do not compare your life with another person's path. A journey or a visit will bring useful news.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(314, "The worry you carry is heavier than the work itself. A journey or a visit will bring useful news.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(315, "Offer your fear at Baba's feet and take the next honest step. A journey or a visit will bring useful news.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(316, "A small act of service will lighten this problem. A journey or a visit will bring useful news.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(317, "Wait with a steady heart. The right time is near. A journey or a visit will bring useful news.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(318, "What looks like a loss will teach you something precious. A journey or a visit will bring useful news.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(319, "Keep your word, even in a small matter. A journey or a visit will bring useful news.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(320, "Prayer in the morning will steady the whole day. A journey or a visit will bring useful news.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(321, "Share what you can, and Baba will fill what you lack. A journey or a visit will bring useful news.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(322, "Do not force a yes or a no. Let the truth ripen. A journey or a visit will bring useful news.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(323, "The person you are thinking of needs your patience. A journey or a visit will bring useful news.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(324, "Go to the temple, sit quietly, and listen. A journey or a visit will bring useful news.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(325, "Your effort is seen. Do not abandon it halfway. A journey or a visit will bring useful news.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(326, "Anger will spoil a good result. Speak tomorrow instead. A journey or a visit will bring useful news.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(327, "Money spent for a good cause will return as peace. A journey or a visit will bring useful news.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(328, "Trust the slow progress. It is still progress. A journey or a visit will bring useful news.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(329, "Baba asks you to be kind to yourself today. A journey or a visit will bring useful news.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(330, "Hold one question, not ten. Clarity comes to a quiet mind. A journey or a visit will bring useful news.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. ఒక ప్రయాణం లేదా కలయిక ఉపయోగకరమైన వార్త తెస్తుంది."),
        BabaAnswer(331, "Keep faith in Baba, even when the path is not clear. Do not lend your name to a false story.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(332, "Patience will open the door that hurry keeps shut. Do not lend your name to a false story.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(333, "Speak the truth gently, and your mind will grow quiet. Do not lend your name to a false story.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(334, "Give a little today, without waiting to be asked. Do not lend your name to a false story.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(335, "What you are waiting for is already on its way. Do not lend your name to a false story.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(336, "Do the work in front of you, and leave the result to Baba. Do not lend your name to a false story.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(337, "A calm mind will see the answer you are searching for. Do not lend your name to a false story.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(338, "Forgive the hurt, and you will sleep in peace. Do not lend your name to a false story.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(339, "This delay is protection, not a refusal. Do not lend your name to a false story.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(340, "Begin the good work you have been postponing. Do not lend your name to a false story.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(341, "Your family will find peace if you speak with kindness. Do not lend your name to a false story.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(342, "Health returns when rest and prayer walk together. Do not lend your name to a false story.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(343, "Do not compare your life with another person's path. Do not lend your name to a false story.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(344, "The worry you carry is heavier than the work itself. Do not lend your name to a false story.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(345, "Offer your fear at Baba's feet and take the next honest step. Do not lend your name to a false story.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(346, "A small act of service will lighten this problem. Do not lend your name to a false story.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(347, "Wait with a steady heart. The right time is near. Do not lend your name to a false story.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(348, "What looks like a loss will teach you something precious. Do not lend your name to a false story.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(349, "Keep your word, even in a small matter. Do not lend your name to a false story.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(350, "Prayer in the morning will steady the whole day. Do not lend your name to a false story.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(351, "Share what you can, and Baba will fill what you lack. Do not lend your name to a false story.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(352, "Do not force a yes or a no. Let the truth ripen. Do not lend your name to a false story.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(353, "The person you are thinking of needs your patience. Do not lend your name to a false story.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(354, "Go to the temple, sit quietly, and listen. Do not lend your name to a false story.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(355, "Your effort is seen. Do not abandon it halfway. Do not lend your name to a false story.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(356, "Anger will spoil a good result. Speak tomorrow instead. Do not lend your name to a false story.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(357, "Money spent for a good cause will return as peace. Do not lend your name to a false story.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(358, "Trust the slow progress. It is still progress. Do not lend your name to a false story.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(359, "Baba asks you to be kind to yourself today. Do not lend your name to a false story.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(360, "Hold one question, not ten. Clarity comes to a quiet mind. Do not lend your name to a false story.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. అబద్ధపు మాటకు మీ పేరు ఇవ్వకండి."),
        BabaAnswer(361, "Keep faith in Baba, even when the path is not clear. The child, the elder, or the guest in your house needs care this week.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(362, "Patience will open the door that hurry keeps shut. The child, the elder, or the guest in your house needs care this week.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(363, "Speak the truth gently, and your mind will grow quiet. The child, the elder, or the guest in your house needs care this week.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(364, "Give a little today, without waiting to be asked. The child, the elder, or the guest in your house needs care this week.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(365, "What you are waiting for is already on its way. The child, the elder, or the guest in your house needs care this week.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(366, "Do the work in front of you, and leave the result to Baba. The child, the elder, or the guest in your house needs care this week.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(367, "A calm mind will see the answer you are searching for. The child, the elder, or the guest in your house needs care this week.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(368, "Forgive the hurt, and you will sleep in peace. The child, the elder, or the guest in your house needs care this week.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(369, "This delay is protection, not a refusal. The child, the elder, or the guest in your house needs care this week.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(370, "Begin the good work you have been postponing. The child, the elder, or the guest in your house needs care this week.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(371, "Your family will find peace if you speak with kindness. The child, the elder, or the guest in your house needs care this week.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(372, "Health returns when rest and prayer walk together. The child, the elder, or the guest in your house needs care this week.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(373, "Do not compare your life with another person's path. The child, the elder, or the guest in your house needs care this week.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(374, "The worry you carry is heavier than the work itself. The child, the elder, or the guest in your house needs care this week.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(375, "Offer your fear at Baba's feet and take the next honest step. The child, the elder, or the guest in your house needs care this week.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(376, "A small act of service will lighten this problem. The child, the elder, or the guest in your house needs care this week.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(377, "Wait with a steady heart. The right time is near. The child, the elder, or the guest in your house needs care this week.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(378, "What looks like a loss will teach you something precious. The child, the elder, or the guest in your house needs care this week.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(379, "Keep your word, even in a small matter. The child, the elder, or the guest in your house needs care this week.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(380, "Prayer in the morning will steady the whole day. The child, the elder, or the guest in your house needs care this week.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(381, "Share what you can, and Baba will fill what you lack. The child, the elder, or the guest in your house needs care this week.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(382, "Do not force a yes or a no. Let the truth ripen. The child, the elder, or the guest in your house needs care this week.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(383, "The person you are thinking of needs your patience. The child, the elder, or the guest in your house needs care this week.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(384, "Go to the temple, sit quietly, and listen. The child, the elder, or the guest in your house needs care this week.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(385, "Your effort is seen. Do not abandon it halfway. The child, the elder, or the guest in your house needs care this week.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(386, "Anger will spoil a good result. Speak tomorrow instead. The child, the elder, or the guest in your house needs care this week.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(387, "Money spent for a good cause will return as peace. The child, the elder, or the guest in your house needs care this week.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(388, "Trust the slow progress. It is still progress. The child, the elder, or the guest in your house needs care this week.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(389, "Baba asks you to be kind to yourself today. The child, the elder, or the guest in your house needs care this week.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(390, "Hold one question, not ten. Clarity comes to a quiet mind. The child, the elder, or the guest in your house needs care this week.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. ఈ వారం మీ ఇంట్లోని పిల్లలు, పెద్దలు లేదా అతిథి మీ శ్రద్ధ కోరుతున్నారు."),
        BabaAnswer(391, "Keep faith in Baba, even when the path is not clear. Study or practise a little every day. Skill grows by returning.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(392, "Patience will open the door that hurry keeps shut. Study or practise a little every day. Skill grows by returning.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(393, "Speak the truth gently, and your mind will grow quiet. Study or practise a little every day. Skill grows by returning.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(394, "Give a little today, without waiting to be asked. Study or practise a little every day. Skill grows by returning.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(395, "What you are waiting for is already on its way. Study or practise a little every day. Skill grows by returning.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(396, "Do the work in front of you, and leave the result to Baba. Study or practise a little every day. Skill grows by returning.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(397, "A calm mind will see the answer you are searching for. Study or practise a little every day. Skill grows by returning.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(398, "Forgive the hurt, and you will sleep in peace. Study or practise a little every day. Skill grows by returning.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(399, "This delay is protection, not a refusal. Study or practise a little every day. Skill grows by returning.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(400, "Begin the good work you have been postponing. Study or practise a little every day. Skill grows by returning.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(401, "Your family will find peace if you speak with kindness. Study or practise a little every day. Skill grows by returning.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(402, "Health returns when rest and prayer walk together. Study or practise a little every day. Skill grows by returning.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(403, "Do not compare your life with another person's path. Study or practise a little every day. Skill grows by returning.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(404, "The worry you carry is heavier than the work itself. Study or practise a little every day. Skill grows by returning.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(405, "Offer your fear at Baba's feet and take the next honest step. Study or practise a little every day. Skill grows by returning.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(406, "A small act of service will lighten this problem. Study or practise a little every day. Skill grows by returning.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(407, "Wait with a steady heart. The right time is near. Study or practise a little every day. Skill grows by returning.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(408, "What looks like a loss will teach you something precious. Study or practise a little every day. Skill grows by returning.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(409, "Keep your word, even in a small matter. Study or practise a little every day. Skill grows by returning.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(410, "Prayer in the morning will steady the whole day. Study or practise a little every day. Skill grows by returning.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(411, "Share what you can, and Baba will fill what you lack. Study or practise a little every day. Skill grows by returning.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(412, "Do not force a yes or a no. Let the truth ripen. Study or practise a little every day. Skill grows by returning.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(413, "The person you are thinking of needs your patience. Study or practise a little every day. Skill grows by returning.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(414, "Go to the temple, sit quietly, and listen. Study or practise a little every day. Skill grows by returning.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(415, "Your effort is seen. Do not abandon it halfway. Study or practise a little every day. Skill grows by returning.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(416, "Anger will spoil a good result. Speak tomorrow instead. Study or practise a little every day. Skill grows by returning.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(417, "Money spent for a good cause will return as peace. Study or practise a little every day. Skill grows by returning.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(418, "Trust the slow progress. It is still progress. Study or practise a little every day. Skill grows by returning.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(419, "Baba asks you to be kind to yourself today. Study or practise a little every day. Skill grows by returning.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(420, "Hold one question, not ten. Clarity comes to a quiet mind. Study or practise a little every day. Skill grows by returning.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. ప్రతి రోజు కొంచెం చదవండి లేదా సాధన చేయండి. తిరిగి చేసే కృషితో నైపుణ్యం పెరుగుతుంది."),
        BabaAnswer(421, "Keep faith in Baba, even when the path is not clear. If the decision can wait a day, let it wait.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(422, "Patience will open the door that hurry keeps shut. If the decision can wait a day, let it wait.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(423, "Speak the truth gently, and your mind will grow quiet. If the decision can wait a day, let it wait.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(424, "Give a little today, without waiting to be asked. If the decision can wait a day, let it wait.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(425, "What you are waiting for is already on its way. If the decision can wait a day, let it wait.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(426, "Do the work in front of you, and leave the result to Baba. If the decision can wait a day, let it wait.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(427, "A calm mind will see the answer you are searching for. If the decision can wait a day, let it wait.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(428, "Forgive the hurt, and you will sleep in peace. If the decision can wait a day, let it wait.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(429, "This delay is protection, not a refusal. If the decision can wait a day, let it wait.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(430, "Begin the good work you have been postponing. If the decision can wait a day, let it wait.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(431, "Your family will find peace if you speak with kindness. If the decision can wait a day, let it wait.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(432, "Health returns when rest and prayer walk together. If the decision can wait a day, let it wait.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(433, "Do not compare your life with another person's path. If the decision can wait a day, let it wait.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(434, "The worry you carry is heavier than the work itself. If the decision can wait a day, let it wait.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(435, "Offer your fear at Baba's feet and take the next honest step. If the decision can wait a day, let it wait.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(436, "A small act of service will lighten this problem. If the decision can wait a day, let it wait.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(437, "Wait with a steady heart. The right time is near. If the decision can wait a day, let it wait.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(438, "What looks like a loss will teach you something precious. If the decision can wait a day, let it wait.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(439, "Keep your word, even in a small matter. If the decision can wait a day, let it wait.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(440, "Prayer in the morning will steady the whole day. If the decision can wait a day, let it wait.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(441, "Share what you can, and Baba will fill what you lack. If the decision can wait a day, let it wait.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(442, "Do not force a yes or a no. Let the truth ripen. If the decision can wait a day, let it wait.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(443, "The person you are thinking of needs your patience. If the decision can wait a day, let it wait.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(444, "Go to the temple, sit quietly, and listen. If the decision can wait a day, let it wait.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(445, "Your effort is seen. Do not abandon it halfway. If the decision can wait a day, let it wait.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(446, "Anger will spoil a good result. Speak tomorrow instead. If the decision can wait a day, let it wait.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(447, "Money spent for a good cause will return as peace. If the decision can wait a day, let it wait.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(448, "Trust the slow progress. It is still progress. If the decision can wait a day, let it wait.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(449, "Baba asks you to be kind to yourself today. If the decision can wait a day, let it wait.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(450, "Hold one question, not ten. Clarity comes to a quiet mind. If the decision can wait a day, let it wait.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. నిర్ణయం ఒక రోజు ఆగగలిగితే, ఆగనివ్వండి."),
        BabaAnswer(451, "Keep faith in Baba, even when the path is not clear. Light a lamp and sit for a few quiet minutes.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(452, "Patience will open the door that hurry keeps shut. Light a lamp and sit for a few quiet minutes.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(453, "Speak the truth gently, and your mind will grow quiet. Light a lamp and sit for a few quiet minutes.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(454, "Give a little today, without waiting to be asked. Light a lamp and sit for a few quiet minutes.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(455, "What you are waiting for is already on its way. Light a lamp and sit for a few quiet minutes.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(456, "Do the work in front of you, and leave the result to Baba. Light a lamp and sit for a few quiet minutes.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(457, "A calm mind will see the answer you are searching for. Light a lamp and sit for a few quiet minutes.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(458, "Forgive the hurt, and you will sleep in peace. Light a lamp and sit for a few quiet minutes.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(459, "This delay is protection, not a refusal. Light a lamp and sit for a few quiet minutes.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(460, "Begin the good work you have been postponing. Light a lamp and sit for a few quiet minutes.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(461, "Your family will find peace if you speak with kindness. Light a lamp and sit for a few quiet minutes.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(462, "Health returns when rest and prayer walk together. Light a lamp and sit for a few quiet minutes.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(463, "Do not compare your life with another person's path. Light a lamp and sit for a few quiet minutes.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(464, "The worry you carry is heavier than the work itself. Light a lamp and sit for a few quiet minutes.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(465, "Offer your fear at Baba's feet and take the next honest step. Light a lamp and sit for a few quiet minutes.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(466, "A small act of service will lighten this problem. Light a lamp and sit for a few quiet minutes.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(467, "Wait with a steady heart. The right time is near. Light a lamp and sit for a few quiet minutes.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(468, "What looks like a loss will teach you something precious. Light a lamp and sit for a few quiet minutes.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(469, "Keep your word, even in a small matter. Light a lamp and sit for a few quiet minutes.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(470, "Prayer in the morning will steady the whole day. Light a lamp and sit for a few quiet minutes.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(471, "Share what you can, and Baba will fill what you lack. Light a lamp and sit for a few quiet minutes.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(472, "Do not force a yes or a no. Let the truth ripen. Light a lamp and sit for a few quiet minutes.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(473, "The person you are thinking of needs your patience. Light a lamp and sit for a few quiet minutes.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(474, "Go to the temple, sit quietly, and listen. Light a lamp and sit for a few quiet minutes.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(475, "Your effort is seen. Do not abandon it halfway. Light a lamp and sit for a few quiet minutes.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(476, "Anger will spoil a good result. Speak tomorrow instead. Light a lamp and sit for a few quiet minutes.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(477, "Money spent for a good cause will return as peace. Light a lamp and sit for a few quiet minutes.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(478, "Trust the slow progress. It is still progress. Light a lamp and sit for a few quiet minutes.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(479, "Baba asks you to be kind to yourself today. Light a lamp and sit for a few quiet minutes.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(480, "Hold one question, not ten. Clarity comes to a quiet mind. Light a lamp and sit for a few quiet minutes.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. దీపం వెలిగించి కొన్ని నిశ్శబ్ద నిమిషాలు కూర్చోండి."),
        BabaAnswer(481, "Keep faith in Baba, even when the path is not clear. What you give in Baba's name should be given freely.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(482, "Patience will open the door that hurry keeps shut. What you give in Baba's name should be given freely.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(483, "Speak the truth gently, and your mind will grow quiet. What you give in Baba's name should be given freely.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(484, "Give a little today, without waiting to be asked. What you give in Baba's name should be given freely.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(485, "What you are waiting for is already on its way. What you give in Baba's name should be given freely.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(486, "Do the work in front of you, and leave the result to Baba. What you give in Baba's name should be given freely.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(487, "A calm mind will see the answer you are searching for. What you give in Baba's name should be given freely.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(488, "Forgive the hurt, and you will sleep in peace. What you give in Baba's name should be given freely.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(489, "This delay is protection, not a refusal. What you give in Baba's name should be given freely.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(490, "Begin the good work you have been postponing. What you give in Baba's name should be given freely.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(491, "Your family will find peace if you speak with kindness. What you give in Baba's name should be given freely.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(492, "Health returns when rest and prayer walk together. What you give in Baba's name should be given freely.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(493, "Do not compare your life with another person's path. What you give in Baba's name should be given freely.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(494, "The worry you carry is heavier than the work itself. What you give in Baba's name should be given freely.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(495, "Offer your fear at Baba's feet and take the next honest step. What you give in Baba's name should be given freely.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(496, "A small act of service will lighten this problem. What you give in Baba's name should be given freely.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(497, "Wait with a steady heart. The right time is near. What you give in Baba's name should be given freely.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(498, "What looks like a loss will teach you something precious. What you give in Baba's name should be given freely.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(499, "Keep your word, even in a small matter. What you give in Baba's name should be given freely.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(500, "Prayer in the morning will steady the whole day. What you give in Baba's name should be given freely.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(501, "Share what you can, and Baba will fill what you lack. What you give in Baba's name should be given freely.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(502, "Do not force a yes or a no. Let the truth ripen. What you give in Baba's name should be given freely.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(503, "The person you are thinking of needs your patience. What you give in Baba's name should be given freely.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(504, "Go to the temple, sit quietly, and listen. What you give in Baba's name should be given freely.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(505, "Your effort is seen. Do not abandon it halfway. What you give in Baba's name should be given freely.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(506, "Anger will spoil a good result. Speak tomorrow instead. What you give in Baba's name should be given freely.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(507, "Money spent for a good cause will return as peace. What you give in Baba's name should be given freely.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(508, "Trust the slow progress. It is still progress. What you give in Baba's name should be given freely.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(509, "Baba asks you to be kind to yourself today. What you give in Baba's name should be given freely.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(510, "Hold one question, not ten. Clarity comes to a quiet mind. What you give in Baba's name should be given freely.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. బాబా పేరుతో ఇచ్చేది ఎదురుచూపు లేకుండా ఇవ్వండి."),
        BabaAnswer(511, "Keep faith in Baba, even when the path is not clear. A friend will stand by you if you ask plainly.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(512, "Patience will open the door that hurry keeps shut. A friend will stand by you if you ask plainly.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(513, "Speak the truth gently, and your mind will grow quiet. A friend will stand by you if you ask plainly.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(514, "Give a little today, without waiting to be asked. A friend will stand by you if you ask plainly.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(515, "What you are waiting for is already on its way. A friend will stand by you if you ask plainly.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(516, "Do the work in front of you, and leave the result to Baba. A friend will stand by you if you ask plainly.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(517, "A calm mind will see the answer you are searching for. A friend will stand by you if you ask plainly.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(518, "Forgive the hurt, and you will sleep in peace. A friend will stand by you if you ask plainly.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(519, "This delay is protection, not a refusal. A friend will stand by you if you ask plainly.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(520, "Begin the good work you have been postponing. A friend will stand by you if you ask plainly.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(521, "Your family will find peace if you speak with kindness. A friend will stand by you if you ask plainly.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(522, "Health returns when rest and prayer walk together. A friend will stand by you if you ask plainly.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(523, "Do not compare your life with another person's path. A friend will stand by you if you ask plainly.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(524, "The worry you carry is heavier than the work itself. A friend will stand by you if you ask plainly.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(525, "Offer your fear at Baba's feet and take the next honest step. A friend will stand by you if you ask plainly.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(526, "A small act of service will lighten this problem. A friend will stand by you if you ask plainly.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(527, "Wait with a steady heart. The right time is near. A friend will stand by you if you ask plainly.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(528, "What looks like a loss will teach you something precious. A friend will stand by you if you ask plainly.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(529, "Keep your word, even in a small matter. A friend will stand by you if you ask plainly.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(530, "Prayer in the morning will steady the whole day. A friend will stand by you if you ask plainly.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(531, "Share what you can, and Baba will fill what you lack. A friend will stand by you if you ask plainly.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(532, "Do not force a yes or a no. Let the truth ripen. A friend will stand by you if you ask plainly.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(533, "The person you are thinking of needs your patience. A friend will stand by you if you ask plainly.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(534, "Go to the temple, sit quietly, and listen. A friend will stand by you if you ask plainly.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(535, "Your effort is seen. Do not abandon it halfway. A friend will stand by you if you ask plainly.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(536, "Anger will spoil a good result. Speak tomorrow instead. A friend will stand by you if you ask plainly.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(537, "Money spent for a good cause will return as peace. A friend will stand by you if you ask plainly.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(538, "Trust the slow progress. It is still progress. A friend will stand by you if you ask plainly.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(539, "Baba asks you to be kind to yourself today. A friend will stand by you if you ask plainly.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(540, "Hold one question, not ten. Clarity comes to a quiet mind. A friend will stand by you if you ask plainly.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. మీరు స్పష్టంగా అడిగితే ఒక మిత్రుడు మీ పక్షం నిలుస్తారు."),
        BabaAnswer(541, "Keep faith in Baba, even when the path is not clear. Do not make a promise you cannot keep.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(542, "Patience will open the door that hurry keeps shut. Do not make a promise you cannot keep.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(543, "Speak the truth gently, and your mind will grow quiet. Do not make a promise you cannot keep.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(544, "Give a little today, without waiting to be asked. Do not make a promise you cannot keep.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(545, "What you are waiting for is already on its way. Do not make a promise you cannot keep.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(546, "Do the work in front of you, and leave the result to Baba. Do not make a promise you cannot keep.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(547, "A calm mind will see the answer you are searching for. Do not make a promise you cannot keep.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(548, "Forgive the hurt, and you will sleep in peace. Do not make a promise you cannot keep.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(549, "This delay is protection, not a refusal. Do not make a promise you cannot keep.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(550, "Begin the good work you have been postponing. Do not make a promise you cannot keep.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(551, "Your family will find peace if you speak with kindness. Do not make a promise you cannot keep.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(552, "Health returns when rest and prayer walk together. Do not make a promise you cannot keep.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(553, "Do not compare your life with another person's path. Do not make a promise you cannot keep.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(554, "The worry you carry is heavier than the work itself. Do not make a promise you cannot keep.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(555, "Offer your fear at Baba's feet and take the next honest step. Do not make a promise you cannot keep.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(556, "A small act of service will lighten this problem. Do not make a promise you cannot keep.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(557, "Wait with a steady heart. The right time is near. Do not make a promise you cannot keep.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(558, "What looks like a loss will teach you something precious. Do not make a promise you cannot keep.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(559, "Keep your word, even in a small matter. Do not make a promise you cannot keep.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(560, "Prayer in the morning will steady the whole day. Do not make a promise you cannot keep.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(561, "Share what you can, and Baba will fill what you lack. Do not make a promise you cannot keep.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(562, "Do not force a yes or a no. Let the truth ripen. Do not make a promise you cannot keep.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(563, "The person you are thinking of needs your patience. Do not make a promise you cannot keep.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(564, "Go to the temple, sit quietly, and listen. Do not make a promise you cannot keep.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(565, "Your effort is seen. Do not abandon it halfway. Do not make a promise you cannot keep.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(566, "Anger will spoil a good result. Speak tomorrow instead. Do not make a promise you cannot keep.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(567, "Money spent for a good cause will return as peace. Do not make a promise you cannot keep.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(568, "Trust the slow progress. It is still progress. Do not make a promise you cannot keep.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(569, "Baba asks you to be kind to yourself today. Do not make a promise you cannot keep.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(570, "Hold one question, not ten. Clarity comes to a quiet mind. Do not make a promise you cannot keep.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. మీరు నిలబెట్టలేని మాట ఇవ్వకండి."),
        BabaAnswer(571, "Keep faith in Baba, even when the path is not clear. The illness or the worry will ease. Continue the care and the prayer.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(572, "Patience will open the door that hurry keeps shut. The illness or the worry will ease. Continue the care and the prayer.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(573, "Speak the truth gently, and your mind will grow quiet. The illness or the worry will ease. Continue the care and the prayer.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(574, "Give a little today, without waiting to be asked. The illness or the worry will ease. Continue the care and the prayer.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(575, "What you are waiting for is already on its way. The illness or the worry will ease. Continue the care and the prayer.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(576, "Do the work in front of you, and leave the result to Baba. The illness or the worry will ease. Continue the care and the prayer.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(577, "A calm mind will see the answer you are searching for. The illness or the worry will ease. Continue the care and the prayer.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(578, "Forgive the hurt, and you will sleep in peace. The illness or the worry will ease. Continue the care and the prayer.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(579, "This delay is protection, not a refusal. The illness or the worry will ease. Continue the care and the prayer.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(580, "Begin the good work you have been postponing. The illness or the worry will ease. Continue the care and the prayer.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(581, "Your family will find peace if you speak with kindness. The illness or the worry will ease. Continue the care and the prayer.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(582, "Health returns when rest and prayer walk together. The illness or the worry will ease. Continue the care and the prayer.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(583, "Do not compare your life with another person's path. The illness or the worry will ease. Continue the care and the prayer.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(584, "The worry you carry is heavier than the work itself. The illness or the worry will ease. Continue the care and the prayer.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(585, "Offer your fear at Baba's feet and take the next honest step. The illness or the worry will ease. Continue the care and the prayer.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(586, "A small act of service will lighten this problem. The illness or the worry will ease. Continue the care and the prayer.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(587, "Wait with a steady heart. The right time is near. The illness or the worry will ease. Continue the care and the prayer.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(588, "What looks like a loss will teach you something precious. The illness or the worry will ease. Continue the care and the prayer.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(589, "Keep your word, even in a small matter. The illness or the worry will ease. Continue the care and the prayer.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(590, "Prayer in the morning will steady the whole day. The illness or the worry will ease. Continue the care and the prayer.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(591, "Share what you can, and Baba will fill what you lack. The illness or the worry will ease. Continue the care and the prayer.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(592, "Do not force a yes or a no. Let the truth ripen. The illness or the worry will ease. Continue the care and the prayer.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(593, "The person you are thinking of needs your patience. The illness or the worry will ease. Continue the care and the prayer.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(594, "Go to the temple, sit quietly, and listen. The illness or the worry will ease. Continue the care and the prayer.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(595, "Your effort is seen. Do not abandon it halfway. The illness or the worry will ease. Continue the care and the prayer.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(596, "Anger will spoil a good result. Speak tomorrow instead. The illness or the worry will ease. Continue the care and the prayer.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(597, "Money spent for a good cause will return as peace. The illness or the worry will ease. Continue the care and the prayer.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(598, "Trust the slow progress. It is still progress. The illness or the worry will ease. Continue the care and the prayer.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(599, "Baba asks you to be kind to yourself today. The illness or the worry will ease. Continue the care and the prayer.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(600, "Hold one question, not ten. Clarity comes to a quiet mind. The illness or the worry will ease. Continue the care and the prayer.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. జబ్బు లేదా చింత తగ్గుతుంది. జాగ్రత్తను మరియు ప్రార్థనను కొనసాగించండి."),
        BabaAnswer(601, "Keep faith in Baba, even when the path is not clear. Pride is the knot in this problem. Loosen it.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(602, "Patience will open the door that hurry keeps shut. Pride is the knot in this problem. Loosen it.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(603, "Speak the truth gently, and your mind will grow quiet. Pride is the knot in this problem. Loosen it.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(604, "Give a little today, without waiting to be asked. Pride is the knot in this problem. Loosen it.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(605, "What you are waiting for is already on its way. Pride is the knot in this problem. Loosen it.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(606, "Do the work in front of you, and leave the result to Baba. Pride is the knot in this problem. Loosen it.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(607, "A calm mind will see the answer you are searching for. Pride is the knot in this problem. Loosen it.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(608, "Forgive the hurt, and you will sleep in peace. Pride is the knot in this problem. Loosen it.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(609, "This delay is protection, not a refusal. Pride is the knot in this problem. Loosen it.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(610, "Begin the good work you have been postponing. Pride is the knot in this problem. Loosen it.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(611, "Your family will find peace if you speak with kindness. Pride is the knot in this problem. Loosen it.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(612, "Health returns when rest and prayer walk together. Pride is the knot in this problem. Loosen it.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(613, "Do not compare your life with another person's path. Pride is the knot in this problem. Loosen it.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(614, "The worry you carry is heavier than the work itself. Pride is the knot in this problem. Loosen it.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(615, "Offer your fear at Baba's feet and take the next honest step. Pride is the knot in this problem. Loosen it.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(616, "A small act of service will lighten this problem. Pride is the knot in this problem. Loosen it.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(617, "Wait with a steady heart. The right time is near. Pride is the knot in this problem. Loosen it.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(618, "What looks like a loss will teach you something precious. Pride is the knot in this problem. Loosen it.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(619, "Keep your word, even in a small matter. Pride is the knot in this problem. Loosen it.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(620, "Prayer in the morning will steady the whole day. Pride is the knot in this problem. Loosen it.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(621, "Share what you can, and Baba will fill what you lack. Pride is the knot in this problem. Loosen it.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(622, "Do not force a yes or a no. Let the truth ripen. Pride is the knot in this problem. Loosen it.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(623, "The person you are thinking of needs your patience. Pride is the knot in this problem. Loosen it.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(624, "Go to the temple, sit quietly, and listen. Pride is the knot in this problem. Loosen it.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(625, "Your effort is seen. Do not abandon it halfway. Pride is the knot in this problem. Loosen it.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(626, "Anger will spoil a good result. Speak tomorrow instead. Pride is the knot in this problem. Loosen it.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(627, "Money spent for a good cause will return as peace. Pride is the knot in this problem. Loosen it.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(628, "Trust the slow progress. It is still progress. Pride is the knot in this problem. Loosen it.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(629, "Baba asks you to be kind to yourself today. Pride is the knot in this problem. Loosen it.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(630, "Hold one question, not ten. Clarity comes to a quiet mind. Pride is the knot in this problem. Loosen it.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. ఈ సమస్యలోని ముడి అహంకారం. దాన్ని వదులు చేయండి."),
        BabaAnswer(631, "Keep faith in Baba, even when the path is not clear. Stay where you are a little longer. Moving in fear will cost more.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(632, "Patience will open the door that hurry keeps shut. Stay where you are a little longer. Moving in fear will cost more.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(633, "Speak the truth gently, and your mind will grow quiet. Stay where you are a little longer. Moving in fear will cost more.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(634, "Give a little today, without waiting to be asked. Stay where you are a little longer. Moving in fear will cost more.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(635, "What you are waiting for is already on its way. Stay where you are a little longer. Moving in fear will cost more.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(636, "Do the work in front of you, and leave the result to Baba. Stay where you are a little longer. Moving in fear will cost more.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(637, "A calm mind will see the answer you are searching for. Stay where you are a little longer. Moving in fear will cost more.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(638, "Forgive the hurt, and you will sleep in peace. Stay where you are a little longer. Moving in fear will cost more.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(639, "This delay is protection, not a refusal. Stay where you are a little longer. Moving in fear will cost more.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(640, "Begin the good work you have been postponing. Stay where you are a little longer. Moving in fear will cost more.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(641, "Your family will find peace if you speak with kindness. Stay where you are a little longer. Moving in fear will cost more.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(642, "Health returns when rest and prayer walk together. Stay where you are a little longer. Moving in fear will cost more.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(643, "Do not compare your life with another person's path. Stay where you are a little longer. Moving in fear will cost more.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(644, "The worry you carry is heavier than the work itself. Stay where you are a little longer. Moving in fear will cost more.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(645, "Offer your fear at Baba's feet and take the next honest step. Stay where you are a little longer. Moving in fear will cost more.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(646, "A small act of service will lighten this problem. Stay where you are a little longer. Moving in fear will cost more.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(647, "Wait with a steady heart. The right time is near. Stay where you are a little longer. Moving in fear will cost more.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(648, "What looks like a loss will teach you something precious. Stay where you are a little longer. Moving in fear will cost more.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(649, "Keep your word, even in a small matter. Stay where you are a little longer. Moving in fear will cost more.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(650, "Prayer in the morning will steady the whole day. Stay where you are a little longer. Moving in fear will cost more.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(651, "Share what you can, and Baba will fill what you lack. Stay where you are a little longer. Moving in fear will cost more.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(652, "Do not force a yes or a no. Let the truth ripen. Stay where you are a little longer. Moving in fear will cost more.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(653, "The person you are thinking of needs your patience. Stay where you are a little longer. Moving in fear will cost more.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(654, "Go to the temple, sit quietly, and listen. Stay where you are a little longer. Moving in fear will cost more.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(655, "Your effort is seen. Do not abandon it halfway. Stay where you are a little longer. Moving in fear will cost more.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(656, "Anger will spoil a good result. Speak tomorrow instead. Stay where you are a little longer. Moving in fear will cost more.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(657, "Money spent for a good cause will return as peace. Stay where you are a little longer. Moving in fear will cost more.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(658, "Trust the slow progress. It is still progress. Stay where you are a little longer. Moving in fear will cost more.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(659, "Baba asks you to be kind to yourself today. Stay where you are a little longer. Moving in fear will cost more.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(660, "Hold one question, not ten. Clarity comes to a quiet mind. Stay where you are a little longer. Moving in fear will cost more.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. ఇంకొంచెం కాలం ఇక్కడే ఉండండి. భయంతో కదలడం ఎక్కువ నష్టం తెస్తుంది."),
        BabaAnswer(661, "Keep faith in Baba, even when the path is not clear. Baba's blessing rests on the one who does not harm another for gain.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(662, "Patience will open the door that hurry keeps shut. Baba's blessing rests on the one who does not harm another for gain.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(663, "Speak the truth gently, and your mind will grow quiet. Baba's blessing rests on the one who does not harm another for gain.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(664, "Give a little today, without waiting to be asked. Baba's blessing rests on the one who does not harm another for gain.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(665, "What you are waiting for is already on its way. Baba's blessing rests on the one who does not harm another for gain.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(666, "Do the work in front of you, and leave the result to Baba. Baba's blessing rests on the one who does not harm another for gain.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(667, "A calm mind will see the answer you are searching for. Baba's blessing rests on the one who does not harm another for gain.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(668, "Forgive the hurt, and you will sleep in peace. Baba's blessing rests on the one who does not harm another for gain.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(669, "This delay is protection, not a refusal. Baba's blessing rests on the one who does not harm another for gain.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(670, "Begin the good work you have been postponing. Baba's blessing rests on the one who does not harm another for gain.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(671, "Your family will find peace if you speak with kindness. Baba's blessing rests on the one who does not harm another for gain.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(672, "Health returns when rest and prayer walk together. Baba's blessing rests on the one who does not harm another for gain.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(673, "Do not compare your life with another person's path. Baba's blessing rests on the one who does not harm another for gain.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(674, "The worry you carry is heavier than the work itself. Baba's blessing rests on the one who does not harm another for gain.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(675, "Offer your fear at Baba's feet and take the next honest step. Baba's blessing rests on the one who does not harm another for gain.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(676, "A small act of service will lighten this problem. Baba's blessing rests on the one who does not harm another for gain.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(677, "Wait with a steady heart. The right time is near. Baba's blessing rests on the one who does not harm another for gain.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(678, "What looks like a loss will teach you something precious. Baba's blessing rests on the one who does not harm another for gain.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(679, "Keep your word, even in a small matter. Baba's blessing rests on the one who does not harm another for gain.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(680, "Prayer in the morning will steady the whole day. Baba's blessing rests on the one who does not harm another for gain.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(681, "Share what you can, and Baba will fill what you lack. Baba's blessing rests on the one who does not harm another for gain.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(682, "Do not force a yes or a no. Let the truth ripen. Baba's blessing rests on the one who does not harm another for gain.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(683, "The person you are thinking of needs your patience. Baba's blessing rests on the one who does not harm another for gain.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(684, "Go to the temple, sit quietly, and listen. Baba's blessing rests on the one who does not harm another for gain.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(685, "Your effort is seen. Do not abandon it halfway. Baba's blessing rests on the one who does not harm another for gain.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(686, "Anger will spoil a good result. Speak tomorrow instead. Baba's blessing rests on the one who does not harm another for gain.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(687, "Money spent for a good cause will return as peace. Baba's blessing rests on the one who does not harm another for gain.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(688, "Trust the slow progress. It is still progress. Baba's blessing rests on the one who does not harm another for gain.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(689, "Baba asks you to be kind to yourself today. Baba's blessing rests on the one who does not harm another for gain.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(690, "Hold one question, not ten. Clarity comes to a quiet mind. Baba's blessing rests on the one who does not harm another for gain.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. లాభం కోసం ఇతరులకు హాని చేయని వారిపై బాబా దీవెన ఉంటుంది."),
        BabaAnswer(691, "Keep faith in Baba, even when the path is not clear. End the day by remembering one kindness you received.", "దారి స్పష్టంగా కనిపించనప్పుడు కూడా బాబాపై విశ్వాసం ఉంచండి. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(692, "Patience will open the door that hurry keeps shut. End the day by remembering one kindness you received.", "తొందర మూసివేసే తలుపును ఓర్పు తెరుస్తుంది. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(693, "Speak the truth gently, and your mind will grow quiet. End the day by remembering one kindness you received.", "సత్యాన్ని మృదువుగా చెప్పండి. అప్పుడు మీ మనసు ప్రశాంతమవుతుంది. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(694, "Give a little today, without waiting to be asked. End the day by remembering one kindness you received.", "ఎవరూ అడగకముందే ఈరోజు కొంచెం ఇవ్వండి. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(695, "What you are waiting for is already on its way. End the day by remembering one kindness you received.", "మీరు ఎదురుచూస్తున్నది ఇప్పటికే మీ వైపు వస్తోంది. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(696, "Do the work in front of you, and leave the result to Baba. End the day by remembering one kindness you received.", "మీ ముందున్న పని చేయండి. ఫలితాన్ని బాబాకు వదిలేయండి. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(697, "A calm mind will see the answer you are searching for. End the day by remembering one kindness you received.", "ప్రశాంతమైన మనసు మీరు వెతుకుతున్న సమాధానాన్ని చూపుతుంది. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(698, "Forgive the hurt, and you will sleep in peace. End the day by remembering one kindness you received.", "ఆ బాధను క్షమించండి. అప్పుడు మీరు ప్రశాంతంగా నిద్రపోతారు. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(699, "This delay is protection, not a refusal. End the day by remembering one kindness you received.", "ఈ ఆలస్యం నిరాకరణ కాదు. ఇది రక్షణ. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(700, "Begin the good work you have been postponing. End the day by remembering one kindness you received.", "మీరు వాయిదా వేస్తున్న మంచి పనిని ఈరోజే ప్రారంభించండి. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(701, "Your family will find peace if you speak with kindness. End the day by remembering one kindness you received.", "మీరు దయతో మాట్లాడితే మీ కుటుంబానికి శాంతి లభిస్తుంది. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(702, "Health returns when rest and prayer walk together. End the day by remembering one kindness you received.", "విశ్రాంతి మరియు ప్రార్థన కలిసి నడిస్తే ఆరోగ్యం తిరిగి వస్తుంది. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(703, "Do not compare your life with another person's path. End the day by remembering one kindness you received.", "మీ జీవితాన్ని ఇంకొకరి దారితో పోల్చకండి. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(704, "The worry you carry is heavier than the work itself. End the day by remembering one kindness you received.", "మీరు మోస్తున్న చింత, పని కంటే బరువుగా ఉంది. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(705, "Offer your fear at Baba's feet and take the next honest step. End the day by remembering one kindness you received.", "మీ భయాన్ని బాబా పాదాల వద్ద ఉంచి, తర్వాతి నిజాయితీ అడుగు వేయండి. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(706, "A small act of service will lighten this problem. End the day by remembering one kindness you received.", "ఒక చిన్న సేవ ఈ సమస్యను తేలిక చేస్తుంది. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(707, "Wait with a steady heart. The right time is near. End the day by remembering one kindness you received.", "నిలకడగల హృదయంతో వేచి ఉండండి. సరైన సమయం దగ్గరలో ఉంది. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(708, "What looks like a loss will teach you something precious. End the day by remembering one kindness you received.", "నష్టంలా కనిపించేది మీకు విలువైన పాఠం నేర్పుతుంది. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(709, "Keep your word, even in a small matter. End the day by remembering one kindness you received.", "చిన్న విషయంలో కూడా మీ మాటను నిలబెట్టుకోండి. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(710, "Prayer in the morning will steady the whole day. End the day by remembering one kindness you received.", "ఉదయం ప్రార్థన రోజంతా మిమ్మల్ని నిలకడగా ఉంచుతుంది. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(711, "Share what you can, and Baba will fill what you lack. End the day by remembering one kindness you received.", "మీ వల్లైనంత పంచుకోండి. లేనిది బాబా నింపుతారు. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(712, "Do not force a yes or a no. Let the truth ripen. End the day by remembering one kindness you received.", "అవును లేదా కాదు అని బలవంతం చేయకండి. సత్యం పండనివ్వండి. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(713, "The person you are thinking of needs your patience. End the day by remembering one kindness you received.", "మీరు తలుస్తున్న వ్యక్తికి మీ ఓర్పు అవసరం. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(714, "Go to the temple, sit quietly, and listen. End the day by remembering one kindness you received.", "గుడికి వెళ్లి, నిశ్శబ్దంగా కూర్చుని వినండి. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(715, "Your effort is seen. Do not abandon it halfway. End the day by remembering one kindness you received.", "మీ కృషి కనిపిస్తోంది. దాన్ని సగంలో వదిలేయకండి. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(716, "Anger will spoil a good result. Speak tomorrow instead. End the day by remembering one kindness you received.", "కోపం మంచి ఫలితాన్ని పాడు చేస్తుంది. రేపు మాట్లాడండి. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(717, "Money spent for a good cause will return as peace. End the day by remembering one kindness you received.", "మంచి పనికి ఖర్చు చేసిన ధనం శాంతిగా తిరిగి వస్తుంది. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(718, "Trust the slow progress. It is still progress. End the day by remembering one kindness you received.", "నెమ్మదైన పురోగతిని నమ్మండి. అది కూడా పురోగతే. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(719, "Baba asks you to be kind to yourself today. End the day by remembering one kindness you received.", "ఈరోజు మీ పట్ల దయగా ఉండమని బాబా అడుగుతున్నారు. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
        BabaAnswer(720, "Hold one question, not ten. Clarity comes to a quiet mind. End the day by remembering one kindness you received.", "పది ప్రశ్నలు కాదు, ఒక్క ప్రశ్నను పట్టుకోండి. ప్రశాంతమైన మనసుకు స్పష్టత వస్తుంది. మీరు పొందిన ఒక దయను గుర్తు చేసుకుని రోజును ముగించండి."),
    )
}
